// Spec-style helper: checks the intended property for all indices.
// (In plain Rust this is just a normal function; kept to mirror the prompt.)
fn all_odd_at_odd_positions(arr: &Vec<usize>) -> bool {
    // For every index i, arr[i] and i must have the same parity.
    arr.iter()
        .enumerate()
        .all(|(i, &v)| ((i ^ v) & 1) == 0)
}

// Requested function: returns true iff every even index holds an even value
// and every odd index holds an odd value.
fn is_odd_at_odd_index(arr: &Vec<usize>) -> bool {
    all_odd_at_odd_positions(arr)
}

